"use client"

import Link from "next/link"
import { useState } from "react"
import { Menu, X } from "lucide-react"

export default function Header() {
  const [isOpen, setIsOpen] = useState(false)

  const toggleMenu = () => setIsOpen(!isOpen)

  return (
    <header className="sticky top-0 z-50 w-full bg-background/95 backdrop-blur border-b border-border">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex-shrink-0 flex items-center">
            <Link href="/" className="flex items-center gap-3">
              <img src="/imageagape.jpeg" alt="Mission Agape" className="h-10 w-10 rounded-full object-cover" />
              <span className="text-2xl font-extrabold tracking-tight" style={{ color: 'var(--logo-red)' }}>
                Agape
              </span>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex gap-6 items-center navbar">
            <Link href="/" className="nav-link text-muted transition font-medium" aria-current="page">
              Accueil
            </Link>
            <Link href="/#ecoles" className="nav-link text-muted transition font-medium">
              Écoles
            </Link>
            <Link href="/ecoles/bible-inductive" className="nav-link text-muted transition font-medium">
              Bible
            </Link>
            <Link href="/contact" className="nav-link text-muted transition font-medium">
              Contact
            </Link>
            <div className="ml-3">
              <Link href="/contact" className="btn-primary">
                S'inscrire
              </Link>
            </div>
          </nav>

          {/* Mobile Menu Button */}
          <button
            onClick={toggleMenu}
            className="md:hidden inline-flex items-center justify-center p-2 text-foreground hover:text-primary"
            aria-label="Menu"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>

        {/* Mobile Navigation */}
        {isOpen && (
          <div className="md:hidden pb-4 border-t border-border">
            <Link
              href="/"
              className="block py-2 text-muted nav-link-mobile transition"
              onClick={() => setIsOpen(false)}
            >
              Accueil
            </Link>
            <Link
              href="/#ecoles"
              className="block py-2 text-muted nav-link-mobile transition"
              onClick={() => setIsOpen(false)}
            >
              Écoles
            </Link>
            <Link
              href="/contact"
              className="block py-2 text-muted nav-link-mobile transition"
              onClick={() => setIsOpen(false)}
            >
              Contact
            </Link>
          </div>
        )}
      </div>
    </header>
  )
}
